import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "dayjs/locale/en-gb";
import { useDispatch } from "react-redux";
import { getLoggedInUser } from "../../../helpers/authUtils";

import useApi from "../../../hooks/useApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import { Modal } from "antd";
import usersApi from "../../../api/usersApi";

export default function ClientVerifyFormModal({
   openverifyModal,
  setopenVerifyModal,
  selectedClient,
  updated, setUpdated,
 phoneToVerify
}) {
  const [user, setUser] = useState();
  const [errors, setErrors] = useState();
  const { currentColor, loggedInUser } = useStateContext();


  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);


  //Formik

  const [disableResend, setdisableResend] = useState(true);

  const formik = useFormik({
    initialValues: {
      phone: phoneToVerify?phoneToVerify:"",
      otp: "",
    },

    validationSchema: Yup.object({
      phone: Yup.string().required().label("Phone number is required"),
      otp: Yup.string().min(4).max(4).required().label("OTP is required"),
    }),

    onSubmit: (values, { resetForm }) => {
      console.log("VALZ", values);

      const data = {
        action: "VerifyCorporateUserOTP",
        otp: values.otp,
        phone: values.phone,
      };

      verifyOTP(data)
    },
  });

  //Verify user OTP

  const verifyCorporateUserOTPApi = useApi(usersApi.usersAction);

  const verifyOTP = async (data) => {
    await verifyCorporateUserOTPApi.request(data);
  };
  useEffect(() => {
    if (verifyCorporateUserOTPApi.data) {
      if (verifyCorporateUserOTPApi.data.user) {
        toast.success(verifyCorporateUserOTPApi.data.response_message);
        setopenVerifyModal(false)
        setUpdated(true)
      } else {
        toast.error(verifyCorporateUserOTPApi.data.response_message);
      }

      if (verifyCorporateUserOTPApi.data.errors) {
        setErrors(verifyCorporateUserOTPApi.data.errors);
        setdisableResend(true)
      }
    }

    console.log("verifyCorporateUserOTPApi.data", verifyCorporateUserOTPApi.data);
  }, [verifyCorporateUserOTPApi.data]);

  const handleOk = () => {
    setopenVerifyModal(false);
  };
  const handleCancel = () => {
    setopenVerifyModal(false);
  };


  const handleResendOTP = () => {};

  return (
    <div className=" max-w-fit min-w-fit">
      <ToastContainer theme="colored" position="bottom-center" />
      <Modal
        width={800}
        className="w-full text-center capitalize"
        title="VERIFY PHONE NUMBER USING OTP"
        open={openverifyModal}
        onOk={handleOk}
        onCancel={handleCancel}
        closeIcon={true}
        closable={false}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" w-full"
        >
          <div className="grid grid-cols-1 md:grid-cols-2  gap-4  justify-center items-center px-5 w-full">
            <CustomFormItem
              touched={formik.touched.phone}
              error={formik.errors.phone}
            >
              <CustomInput
                id="phone"
                name="phone"
                onChange={formik.handleChange}
                placeholder="Enter  phone number"
                size="large"
                type="text"
                value={formik.values.phone}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.otp}
              error={formik.errors.otp}
            >
              <CustomInput
                id="otp"
                name="otp"
                onChange={formik.handleChange}
                placeholder="Enter OTP number"
                size="large"
                type="text"
                value={formik.values.otp}
              />
            </CustomFormItem>
          </div>

          <div className="px-5 my-5 grid grid-cols-1 md:grid-cols-2 gap-4">
            {disableResend ? (
              <button
                disabled={disableResend}
                onClick={() => handleResendOTP()}
                className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50  disabled bg-gray-200"
                type="button"
              >
                Resend OTP
              </button>
            ) : (
              <button
                disabled={disableResend}
                onClick={() => handleResendOTP()}
                style={{ background: currentColor }}
                className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50 "
                color="primary"
                type="button"
              >
                Resend OTP
              </button>
            )}

            <button
              style={{ background: currentColor }}
              className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50 "
              color="primary"
              type="submit"
            >
              Submit
            </button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
