import React, { useEffect, useState } from 'react'
import UsersTable from './ClientsTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import usersApi from '../../../api/usersApi';
import { Loading } from '../../../components';
import { useStateContext } from '../../../contexts/ContextProvider';
import ClientFormModal from './ClientFormModal';
import ClientVerifyFormModal from './ClientVerifyFormModal';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Gender", uid: "gender" },
    { name: "Date Of Birth", uid: "date_of_birth" },
    { name: "Phone", uid: "phone" },
    { name: "Email", uid: "email" },
    { name: "Roles", uid: "roles_string" },
    { name: "Actions", uid: "actions" },
];


function ClientsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const {loggedInUser}= useStateContext()

    const navigate = useNavigate()
    const [user, setUser] = useState()
    const [users, setUsers] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const usersActionsApi = useApi(usersApi.usersAction)
    const [phoneToVerify, setphoneToVerify] = useState()

    const [openVerifyModal, setopenVerifyModal] = useState(false)

    const getUsers = async () => {
        await usersActionsApi.request({
            "action": "GetEntityUsersById",
            "entity": loggedInUser.entity_id
        })
    }


    useEffect(() => {
        getUsers()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setUser(item)
        setmodalTitle(`Edit ${item.tittle}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new body system")
        setUser(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (usersActionsApi.data && usersActionsApi.data.length) {

            setUsers(usersActionsApi.data)
        }
    }, [usersActionsApi.data])

    useEffect(() => {
        getUsers()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(users)
    }, [users])


    const handleFilter = (e) => {
        const search_param = e
        if (users && users.length > 0 && search_param && search_param !== '') {
            setdata(users.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(users);
        }

    };

    return usersActionsApi.loading ? <Loading loading={usersApi.loading} /> : (
        <div className='mt-16 md:mt-2'>
        {openVerifyModal && <ClientVerifyFormModal phoneToVerify={phoneToVerify} openverifyModal={openVerifyModal} setopenVerifyModal={setopenVerifyModal} selectedClient={user} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {openEditModal && <ClientFormModal setPhoneToVerify={setphoneToVerify}  openVerifyModal={openVerifyModal} setopenVerifyModal={setopenVerifyModal} openEditModal={openEditModal} setopenEditModal={setopenEditModal} selectedClient={user} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <UsersTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default ClientsList